// ============================================================================
// Module: tb_trace_cross_val
// Author: Priyanshu (Performance Analyst & Synthesis Lead)
// Project: Design and Analysis of a Direct-Mapped Cache Controller
// Description: Automated trace player for RTL vs Python cross-validation.
//              Plays address traces generated by analysis/trace_generator.py,
//              measures hardware hits, misses, refills, and data correctness.
// ============================================================================

`timescale 1ns / 1ps

module tb_trace_cross_val;

    localparam ADDR_WIDTH   = 32;
    localparam DATA_WIDTH   = 32;
    localparam BLOCK_WIDTH  = 128;
    localparam TAG_WIDTH    = 22;
    localparam INDEX_WIDTH  = 6;
    localparam OFFSET_WIDTH = 4;
    localparam NUM_LINES    = 64;
    localparam MEM_LATENCY  = 10;   // Baseline 10 cycles
    localparam CLK_PERIOD   = 10;   // 100 MHz

    reg                   clk;
    reg                   rst_n;
    reg                   cpu_req_val;
    reg  [ADDR_WIDTH-1:0] cpu_req_addr;
    wire                  cpu_req_ready;
    wire                  cpu_resp_val;
    wire [DATA_WIDTH-1:0] cpu_resp_data;
    wire [2:0]            fsm_state;
    wire                  hit_out;
    wire                  miss_out;

    // DUT Instantiation
    cache_top #(
        .ADDR_WIDTH   (ADDR_WIDTH),
        .DATA_WIDTH   (DATA_WIDTH),
        .BLOCK_WIDTH  (BLOCK_WIDTH),
        .TAG_WIDTH    (TAG_WIDTH),
        .INDEX_WIDTH  (INDEX_WIDTH),
        .OFFSET_WIDTH (OFFSET_WIDTH),
        .NUM_LINES    (NUM_LINES),
        .MEM_LATENCY  (MEM_LATENCY)
    ) dut (
        .clk           (clk),
        .rst_n         (rst_n),
        .cpu_req_val   (cpu_req_val),
        .cpu_req_addr  (cpu_req_addr),
        .cpu_req_ready (cpu_req_ready),
        .cpu_resp_val  (cpu_resp_val),
        .cpu_resp_data (cpu_resp_data),
        .fsm_state     (fsm_state),
        .hit_out       (hit_out),
        .miss_out      (miss_out)
    );

    // Clock Generation
    initial clk = 1'b0;
    always #(CLK_PERIOD/2) clk = ~clk;

    // Trace Storage
    reg [ADDR_WIDTH-1:0] trace_mem [0:4095];
    integer trace_length = 0;
    integer trace_idx;
    string trace_file;
    string workload_name;

    // Hardware Telemetry Counters
    integer rtl_accesses = 0;
    integer rtl_hits     = 0;
    integer rtl_misses   = 0;
    integer rtl_refills  = 0;
    integer data_errors  = 0;

    // Monitor refills directly from controller write enable
    always @(posedge clk) begin
        if (rst_n && dut.u_cache_controller.cache_write_en) begin
            rtl_refills <= rtl_refills + 1;
        end
    end

    // Single access driver
    task execute_access(
        input [ADDR_WIDTH-1:0] addr,
        input integer seq
    );
        reg hit_sampled;
        reg [DATA_WIDTH-1:0] expected_data;
        integer timeout;
        begin
            rtl_accesses = rtl_accesses + 1;

            // Wait until ready
            timeout = 500;
            while (!cpu_req_ready && timeout > 0) begin
                @(posedge clk);
                timeout = timeout - 1;
            end
            if (timeout == 0) begin
                $display("[FATAL] DUT stuck not ready before seq %0d", seq);
                $finish;
            end

            // Assert request
            @(posedge clk);
            cpu_req_val  <= 1'b1;
            cpu_req_addr <= addr;

            @(posedge clk);
            cpu_req_val  <= 1'b0;

            // Sample hit/miss during LOOKUP (state 3'b001)
            timeout = 500;
            while (fsm_state != 3'b001 && timeout > 0) begin
                @(posedge clk);
                timeout = timeout - 1;
            end
            hit_sampled = hit_out;

            if (hit_sampled) begin
                rtl_hits = rtl_hits + 1;
            end else begin
                rtl_misses = rtl_misses + 1;
            end

            // Wait for response
            timeout = 500;
            while (!cpu_resp_val && timeout > 0) begin
                @(posedge clk);
                timeout = timeout - 1;
            end

            if (timeout == 0) begin
                $display("[FATAL] Timeout waiting for response at seq %0d", seq);
                $finish;
            end

            // Verify Data Correctness
            // Deterministic memory pattern: expected word data is word-aligned address
            expected_data = addr & ~32'h3;
            if (cpu_resp_data !== expected_data) begin
                $display("[DATA ERROR] Seq %0d: Addr=0x%08h Expected=0x%08h Got=0x%08h",
                         seq, addr, expected_data, cpu_resp_data);
                data_errors = data_errors + 1;
            end

            @(posedge clk);
        end
    endtask

    initial begin
        cpu_req_val  = 1'b0;
        cpu_req_addr = 32'h0;
        rst_n        = 1'b0;

        if (!$value$plusargs("TRACE=%s", trace_file)) begin
            trace_file = "traces/sequential_trace.hex";
        end
        if (!$value$plusargs("NAME=%s", workload_name)) begin
            workload_name = "Sequential";
        end

        // Read trace
        $readmemh(trace_file, trace_mem);

        // Count non-zero or valid trace entries
        trace_length = 0;
        while (trace_length < 4096 && trace_mem[trace_length] !== 32'hx) begin
            trace_length = trace_length + 1;
        end

        // Hardware Reset
        #(CLK_PERIOD * 3);
        rst_n = 1'b1;
        #(CLK_PERIOD * 2);

        // Execute all trace accesses
        for (trace_idx = 0; trace_idx < trace_length; trace_idx = trace_idx + 1) begin
            execute_access(trace_mem[trace_idx], trace_idx);
        end

        #(CLK_PERIOD * 5);

        // Emit standardized telemetry line for Python parser
        $display("[RTL_RESULT] Workload=%0s Accesses=%0d Hits=%0d Misses=%0d Refills=%0d DataErrors=%0d",
                 workload_name, rtl_accesses, rtl_hits, rtl_misses, rtl_refills, data_errors);

        $finish;
    end

endmodule
